-- ============================================================================
-- 150_fixtures_price_hourly.sql — FIXTURE déploiement (démo)
-- Prix horaires 30 jours (heures creuses 23h-7h à 0.1299 €/kWh, pleines 0.1874, pics ×1.35),
-- site 'ALL' (prix marché). Identiques aux fixtures front (app-features/fixtures).
-- Démo : remplace les données partielles du flux bronze par la fixture complète.
-- ============================================================================
DELETE FROM bronze.energy_price;
REFRESH MATERIALIZED VIEW gold.price_hourly;

-- Config price-optimizer (sans shiftable_kwh, aucun créneau n'est conseillé : cap = 0).
UPDATE app.prefs
SET prefs = jsonb_set(prefs, '{price-optimizer}',
  coalesce(prefs->'price-optimizer', '{}'::jsonb)
  || jsonb_build_object('enabled', true, 'config', jsonb_build_object('shiftable_kwh', 120, 'window', '01:00-06:00')));
